<script setup lang="ts">
import { useScopedRefresh } from '../scoped-refresh';
import { isHR } from '../policy';
import { useFeedback } from '../feedback';
import { markDirty } from '../workspace';
import { formatBeijing,stateLabel,eventLabel } from '../presentation';
import { ref, onMounted, computed } from 'vue';
import { ApiError,me, listDepartments, type Department } from '../api';
import { all, courseApi, downloadEmployees, importEmployees, saveFile, errorText, tag, type Employee, type Position, type Page, type ImportResult } from '../course-api';
const props=withDefaults(defineProps<{filesOnly?:boolean}>(),{filesOnly:false});
const pageSize=ref(20),canExport=ref(false);
const tabPath=props.filesOnly?'/employee-files':'/employees';
let loadGeneration=0;
const items=ref<Employee[]>([]), positions=ref<Position[]>([]), departments=ref<Department[]>([]), canWrite=ref(false), q=ref(''), depFilter=ref(''), statusFilter=ref('');
const page=ref(1), total=ref(0), busy=ref(false), loading=ref(false), error=ref(''), notice=ref(''), selected=ref<Employee|null>(null);
const mode=ref<'create'|'edit'|'detail'|'transfer'|null>(null);
const blank=()=>({employee_no:'',full_name:'',current_department_id:'',current_position_id:'',hire_date:new Date().toISOString().slice(0,10),employment_status:'ACTIVE'});
const form=ref(blank()), transfer=ref({department_id:'',position_id:''});
const file=ref<File|null>(null), format=ref<'csv'|'xlsx'>('csv'), preflight=ref<ImportResult|null>(null);
const departmentName=(id:string)=>departments.value.find(d=>d.id===id)?.name||'名称未加载';
const positionName=(id:string)=>positions.value.find(p=>p.id===id)?.name||'名称未加载';
const available=computed(()=>positions.value.filter(p=>p.status==='ACTIVE'&&p.department_id===form.value.current_department_id));
async function load(strict=false){const mine=++loadGeneration;loading.value=true;error.value='';try{const query=new URLSearchParams({q:q.value,page:String(page.value),page_size:String(pageSize.value),...(depFilter.value?{department_id:depFilter.value}:{}),...(statusFilter.value?{status:statusFilter.value}:{})});const data=await courseApi<Page<Employee>>(`/employees?${query}`);if(mine===loadGeneration){items.value=data.items;total.value=data.total;}}catch(e){if(mine===loadGeneration){items.value=[];total.value=0;error.value=errorText(e);}if(strict===true)throw e;}finally{if(mine===loadGeneration)loading.value=false;}}
async function open(item:Employee|null,action:typeof mode.value){error.value='';try{selected.value=item?await courseApi<Employee>(`/employees/${encodeURIComponent(item.id)}`):null;mode.value=action;form.value=selected.value?{employee_no:selected.value.employee_no,full_name:selected.value.full_name,current_department_id:selected.value.current_department_id,current_position_id:selected.value.current_position_id,hire_date:selected.value.hire_date,employment_status:selected.value.employment_status}:blank();transfer.value={department_id:'',position_id:''};}catch(e){error.value=errorText(e);}}
async function save(){busy.value=true;error.value='';notice.value='';try{
  if(mode.value==='transfer'&&selected.value)await courseApi(`/employees/${encodeURIComponent(selected.value.id)}/transfer`,'POST',transfer.value,tag(selected.value));
  else if(selected.value)await courseApi(`/employees/${encodeURIComponent(selected.value.id)}`,'PATCH',form.value,tag(selected.value));
  else await courseApi('/employees','POST',form.value);
  markDirty(tabPath,false);notice.value='员工档案已保存';mode.value=null;await load();
}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function archive(item:Employee){if(!window.confirm('确认将该虚构/员工档案离职归档？历史将保留，账号会话将撤销。'))return;busy.value=true;error.value='';notice.value='';try{const latest=await courseApi<Employee>(`/employees/${encodeURIComponent(item.id)}`);await courseApi(`/employees/${encodeURIComponent(item.id)}/archive`,'POST',{},tag(latest));notice.value='已离职归档';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function pick(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null;preflight.value=null;error.value='';notice.value='';if(file.value)format.value=file.value.name.toLowerCase().endsWith('.xlsx')?'xlsx':'csv';}
async function upload(commit=false){if(!file.value)return;busy.value=true;error.value='';notice.value='';try{preflight.value=await importEmployees(file.value,format.value,commit?'commit':'preflight');if(preflight.value.valid&&commit){notice.value=`已原子导入 ${preflight.value.imported} 名员工`;markDirty(tabPath,false,'file');file.value=null;await load();}}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function download(kind:'csv'|'xlsx',template=false){busy.value=true;error.value='';try{saveFile(await downloadEmployees(kind,template,q.value,depFilter.value,statusFilter.value),`employees${template?'-template':''}.${kind}`);}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
onMounted(async()=>{try{const profile=await me();canWrite.value=isHR(profile);canExport.value=canWrite.value||(profile.roles.includes('MANAGER')&&!!profile.employee_id&&profile.employment_valid!==false);positions.value=await all<Position>('/positions');let p=1;for(;;){const result=await listDepartments('',p,100);departments.value.push(...result.items);if(departments.value.length>=result.total)break;p++;}await load();}catch(e){error.value=errorText(e);}});
const {scopeLocked,scopeFailure,retryScope}=useScopedRefresh(async()=>{
 await load(true);
 if(selected.value){try{const fresh=await courseApi<Employee>(`/employees/${encodeURIComponent(selected.value.id)}`);if(mode.value==='detail')selected.value=fresh;}
 catch(e){if(e instanceof ApiError&&[403,404].includes(e.status)){selected.value=null;mode.value=null;form.value=blank();markDirty(tabPath,false);}else throw e;}}
});
useFeedback(notice,error,tabPath);
</script>
<template><div class="business-page"><p v-if="scopeLocked" class="verification" role="status">{{scopeFailure||'正在核验当前数据范围…'}}<button v-if="scopeFailure" @click="retryScope">重试</button></p><main v-show="!scopeLocked">
  <div class="section-heading"><h1>{{props.filesOnly?'员工文件':'员工管理'}}</h1><button v-if="canWrite&&!props.filesOnly" :disabled="busy" @click="open(null,'create')">新增员工</button></div><p v-if="error" class="error feedback" role="alert">{{error}}</p><p v-if="notice" class="success feedback" role="status">{{notice}}</p>
  <section class="card"><form class="search-row" @submit.prevent="page=1;load()"><label>工号 / 姓名<input v-model="q" maxlength="128"></label><label>部门<select aria-label="部门" v-model="depFilter"><option value="">全部授权部门</option><option v-for="d in departments" :value="d.id" :key="d.id">{{d.name}}</option></select></label><label>状态<select aria-label="状态" v-model="statusFilter"><option value="">全部</option><option value="PRE_HIRE">{{stateLabel('PRE_HIRE')}}</option><option value="PROBATION">{{stateLabel('PROBATION')}}</option><option value="ACTIVE">{{stateLabel('ACTIVE')}}</option><option value="EXIT_PROCESSING">{{stateLabel('EXIT_PROCESSING')}}</option><option value="TERMINATED">{{stateLabel('TERMINATED')}}</option></select></label><button :disabled="loading">查询</button></form>
  <template v-if="!props.filesOnly"><p v-if="loading" role="status">加载中…</p><p v-else-if="!items.length" class="muted">当前授权范围暂无匹配员工。</p><div v-else class="table-scroll"><table><thead><tr><th>工号 / 姓名</th><th>部门 / 职位</th><th>入职日</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td>{{row.employee_no}}<br>{{row.full_name}}</td><td>{{departmentName(row.current_department_id)}}<br>{{positionName(row.current_position_id)}}</td><td>{{row.hire_date}}</td><td>{{stateLabel(row.employment_status)}}</td><td><button class="text-button" :disabled="busy" @click="open(row,'detail')">详情 / 历史</button><template v-if="canWrite&&row.employment_status!=='TERMINATED'"><button class="text-button" :disabled="busy" @click="open(row,'edit')">编辑</button><button class="text-button" :disabled="busy" @click="open(row,'transfer')">调动</button><button class="text-button" :disabled="busy||!!mode" @click="archive(row)">离职归档</button></template></td></tr></tbody></table></div>
  <nav class="pagination"><span>共 {{total}} 条 · 第 {{page}} 页</span><label>每页条数<select v-model.number="pageSize" aria-label="每页条数" @change="page=1;load()"><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><button :disabled="page<=1||loading" @click="page--;load()">上一页</button><button :disabled="page*pageSize>=total||loading" @click="page++;load()">下一页</button></nav></template></section>
  <section v-if="mode" class="card"><div class="section-heading"><h2>{{mode==='detail'?'员工详情':mode==='transfer'?'组织调动':mode==='edit'?'编辑员工':'新增员工'}}</h2><button class="secondary" data-clear-dirty @click="mode=null">关闭</button></div>
    <template v-if="mode==='detail'&&selected"><dl><dt>工号 / 姓名</dt><dd>{{selected.employee_no}} · {{selected.full_name}}</dd><dt>部门</dt><dd>{{departmentName(selected.current_department_id)}}</dd><dt>职位</dt><dd>{{positionName(selected.current_position_id)}}</dd><dt>入职日期 / 状态</dt><dd>{{selected.hire_date}} · {{stateLabel(selected.employment_status)}}</dd></dl><h3>变更历史</h3><ul><li v-for="(event,index) in selected.history" :key="index">{{formatBeijing(event.created_at)}} · {{eventLabel(event.event_type)}}<span v-if="event.new_status"> · {{event.old_status?stateLabel(event.old_status):'无'}} → {{stateLabel(event.new_status)}}</span></li></ul><p v-if="!selected.history?.length" class="muted">没有历史事件。</p></template>
    <form v-else @submit.prevent="save"><fieldset :disabled="busy"><template v-if="mode==='transfer'"><label>新部门<select aria-label="新部门" v-model="transfer.department_id" required @change="transfer.position_id=''"><option disabled value="">请选择</option><option v-for="d in departments.filter(x=>x.status==='ACTIVE')" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>新职位<select aria-label="新职位" v-model="transfer.position_id" required><option disabled value="">请选择</option><option v-for="p in positions.filter(x=>x.status==='ACTIVE'&&x.department_id===transfer.department_id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label></template>
    <div v-else class="form-columns"><label>工号<input v-model="form.employee_no" required maxlength="64"></label><label>姓名<input v-model="form.full_name" required maxlength="128"></label><label>部门<select aria-label="部门" v-model="form.current_department_id" :disabled="mode==='edit'" required @change="form.current_position_id=''"><option disabled value="">请选择</option><option v-for="d in departments.filter(x=>x.status==='ACTIVE')" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>职位<select aria-label="职位" v-model="form.current_position_id" :disabled="mode==='edit'" required><option disabled value="">请选择</option><option v-for="p in available" :key="p.id" :value="p.id">{{p.name}} · {{p.grade_code}}</option></select></label><label>入职日期<input v-model="form.hire_date" type="date" required :disabled="mode==='edit'"></label><label>状态<select aria-label="状态" v-model="form.employment_status"><option value="PRE_HIRE">{{stateLabel('PRE_HIRE')}}</option><option value="PROBATION">{{stateLabel('PROBATION')}}</option><option value="ACTIVE">{{stateLabel('ACTIVE')}}</option><option value="EXIT_PROCESSING">{{stateLabel('EXIT_PROCESSING')}}</option></select></label></div><p class="muted">编辑保留归属历史；变更部门与职位请使用“调动”。</p><button>保存员工</button></fieldset></form>
  </section>
  <section v-if="canExport" class="card"><h2>员工文件</h2><p class="muted">导出仅包含授权范围的基础档案，工资和账号不包含在内。</p><div class="form-actions"><button v-for="kind in (['csv','xlsx'] as const)" :key="kind" :disabled="busy" @click="download(kind)">导出 {{kind.toUpperCase()}}（当前查询）</button></div>
    <template v-if="canWrite"><h3>导入</h3><p class="muted">推荐下载中文 XLSX 模板，在第2至101行选择所属部门、所属职位和员工状态；“业务选项”页提供编号与职位所属部门参考。CSV 可填写业务编号或唯一名称；重名请选择模板中的完整业务选项，无需查询数据库ID。</p><p class="muted">入职日期填写 YYYY-MM-DD；员工状态为待入职、试用、在职或离职办理中。模板只列已启用的部门和职位；下载后若发生停用，提交仍会拒绝。旧版六列 ID 格式继续严格校验。</p><div class="form-actions"><button v-for="kind in (['csv','xlsx'] as const)" :key="kind" class="secondary" :disabled="busy" @click="download(kind,true)">下载 {{kind.toUpperCase()}} 模板</button></div><label>选择模板文件<input type="file" accept=".csv,.xlsx" @change="pick"></label><button :disabled="!file||busy" @click="upload()">预检文件</button><button class="secondary" :disabled="!file||busy||!preflight?.valid" @click="upload(true)">导入</button>
    <p v-if="preflight?.valid" class="success" role="status">预检有效；正式提交时服务端会重新校验。已写入 {{preflight.imported}} 条。</p><template v-if="preflight&&!preflight.valid"><p class="error">整批未写入，请按以下行号和原因修正后重新预检。</p><ul class="error" role="alert"><li v-for="(issue,index) in preflight.errors" :key="`${issue.row}-${issue.code}-${index}`">第 {{issue.row}} 行{{issue.field ? ` · ${issue.field}` : ''}}：{{issue.message || '字段或引用不合法，请核对模板'}}</li></ul></template></template>
  </section>
</main></div></template>
